import { StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface MetricCardProps extends Omit<ViewProps, "children"> {
  label: string;
  value: number;
  suffix?: string;
  /** One line of context under the number, such as the previous period. */
  context: string;
  /** Change since the previous period, such as "+15.2%". A leading minus reads as a decrease. */
  change?: string;
  /** Extend the inner, named parts of the metric card: label, value, change or context. The React Native counterpart of `classNames`. */
  styles?: {
    label?: StyleProp<TextStyle>;
    value?: StyleProp<TextStyle>;
    change?: StyleProp<ViewStyle>;
    changeText?: StyleProp<TextStyle>;
    context?: StyleProp<TextStyle>;
  };
}

export function MetricCard({ label, value, suffix, context, change, style, styles: parts, ...props }: MetricCardProps) {
  const tokens = useTokens();
  const down = change?.trim().startsWith("-") || change?.trim().startsWith("−");
  const tone = down ? tokens.danger : tokens.success;

  return (
    <View
      {...props}
      accessible
      accessibilityLabel={`${label}: ${value.toLocaleString()}${suffix ?? ""}${change ? `, ${change}` : ""}. ${context}`}
      style={[local.card, { borderColor: tokens.border, backgroundColor: tokens.surface }, style]}
    >
      <Text style={[local.label, { color: tokens.textSecondary }, parts?.label]}>{label}</Text>
      <View style={local.row}>
        <Text style={[local.value, { color: tokens.foreground }, parts?.value]}>
          {value.toLocaleString()}
          {suffix ? <Text style={{ color: tokens.textMuted, fontSize: metrics.text.sm }}>{suffix}</Text> : null}
        </Text>
        {change ? (
          <View style={[local.change, { backgroundColor: `${tone}1A` }, parts?.change]}>
            <Text style={[{ color: tone, fontSize: metrics.text.xs, fontWeight: "500" }, parts?.changeText]}>{change}</Text>
          </View>
        ) : null}
      </View>
      <Text style={[local.context, { color: tokens.textMuted }, parts?.context]}>{context}</Text>
    </View>
  );
}

const local = StyleSheet.create({
  card: { gap: metrics.space[2], padding: metrics.space[5], borderWidth: 1, borderRadius: 26, alignSelf: "flex-start", minWidth: 200 },
  label: { fontSize: metrics.text.sm },
  row: { flexDirection: "row", alignItems: "baseline", gap: metrics.space[3] },
  value: { fontSize: 30, fontWeight: "600", fontVariant: ["tabular-nums"] },
  change: { paddingHorizontal: 8, paddingVertical: 2, borderRadius: 999 },
  context: { fontSize: metrics.text.xs },
});

export default MetricCard;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
